'use strict';
const ZeroReader=(()=>{
  let documentQuery='';let documents=[],draft={title:'',text:''},active=null,stored=false,loading=false,fetchController=null,returnFocus=null;
  let rawURL=null,persistTimer,progressWrite=Promise.resolve();const pendingSaves=new Set(),saveErrors=new Map();
  let preferences={size:18,line:2,font:'serif',theme:'light'},settingsOpen=false,focused=false;
  const tr=(zh,en)=>t(zh,en),R=ReadingCore;
  const errors={empty:['内容为空，请添加文字或选择文件。','Add some text or choose a non-empty file.'],large:['文件超过 20 MB 限制。','File exceeds the 20 MB limit.'],unsupported:['支持 TXT、Markdown、HTML、PDF 和 DOCX。','Use TXT, Markdown, HTML, PDF or DOCX.'],long:['文字内容过长，最多支持 100 万字符。','Text is too long. Limit: 1 million characters.']};
  function notify(error){toast(errors[error.message]?tr(...errors[error.message]):error.name==='AbortError'?tr('读取已取消或超时。','Loading cancelled or timed out.'):error.message||tr('无法处理此文档。','Could not process this document.'))}
  async function refresh(){try{const all=await dbOp('readonly',store=>store.getAll(),'documents');documents=all.map(({blob,...meta})=>({...meta,words:R.wordCount(meta.text||'')})).sort((a,b)=>b.date-a.date);if(!$('sheet').hidden&&tab==='reading')renderSheet()}catch{toast(tr('无法读取本地文档，请允许浏览器存储。','Could not read documents. Allow browser storage.'))}}
  function libraryHTML(){return `<div class="reading-library"><div class="reading-intro"><span class="reading-mark">${icon('reading')}</span><div><strong>${tr('把文字留下','Keep the words')}</strong><p>${tr('文档与文本，留待安静时阅读。','Documents and notes, ready when you are.')}</p></div></div><div class="reading-actions"><button class="secondary" data-action="readCurrent">${icon('reading')}${tr('阅读当前页面','Read current page')}</button><label class="secondary import-document" for="documentFile" tabindex="0" role="button">${icon('download')}${tr('导入文档','Import document')}</label><input id="documentFile" type="file" accept=".txt,.md,.markdown,.html,.htm,.pdf,.docx" hidden ${loading?'disabled':''}></div><p class="small-note">${tr('支持 TXT、Markdown、HTML、PDF、DOCX · 最大 20 MB。文件在设备本地处理。','TXT, Markdown, HTML, PDF, DOCX · up to 20 MB. Files are processed on this device.')}</p>${loading?`<div class="reading-loading" role="status">${tr('正在提取文字并保存…','Extracting text and saving…')}</div>`:''}<details class="paste-details" ${draft.text?'open':''}><summary>${tr('粘贴一段文字','Paste some text')} <span>＋</span></summary><form id="readingForm"><input id="readingTitle" class="sheet-input" maxlength="160" placeholder="${tr('标题（可选）','Title (optional)')}" value="${esc(draft.title)}" aria-label="${tr('文本标题','Text title')}"><textarea id="readingText" class="sheet-input reading-textarea" placeholder="${tr('把想专注阅读的文字放在这里…','Put the words you want to focus on here…')}" aria-label="${tr('文本内容','Text content')}" maxlength="1000000">${esc(draft.text)}</textarea><button class="primary" type="submit" ${loading?'disabled':''}>${icon('reading')}${tr('缓存并开始阅读','Save and start reading')}</button></form></details><div class="reading-backup-actions"><button data-reader-library="backup">${tr('导出备份','Export backup')}</button><label for="readingBackupFile" tabindex="0">${tr('导入备份','Import backup')}</label><input id="readingBackupFile" type="file" accept=".json" hidden></div><input id="readingSearch" class="sheet-input" type="search" aria-label="${tr('搜索阅读资料','Search reading library')}" placeholder="${tr('搜索标题、全文、标签','Search title, text, tags')}" value="${esc(documentQuery)}"><div class="reading-list-head"><span class="section-label">${tr('离线阅读','OFFLINE READING')} · ${documents.length}</span></div><div id="readingResults">${documents.length?documents.map(doc=>`<div class="item reading-item" ${documentQuery&&![doc.title,doc.text,doc.tag].some(value=>String(value||'').toLocaleLowerCase().includes(documentQuery.toLocaleLowerCase()))?'hidden':''}><button class="item-main" data-read-document="${esc(doc.id)}"><span class="document-kind">${esc(doc.format.toUpperCase())}</span><span class="item-title">${esc(doc.title)}</span><span class="item-sub">${doc.tag?esc(doc.tag)+' · ':''}${doc.words?tr(`${doc.words} 字 · 约 ${Math.max(1,Math.ceil(doc.words/350))} 分钟`,`${doc.words} words · ${Math.max(1,Math.ceil(doc.words/220))} min`):tr('原文件已缓存','Original saved')} · ${tr('已读','Read')} ${Math.round((doc.progress||0)*100)}%</span><span class="document-progress"><span style="width:${Math.round((doc.progress||0)*100)}%"></span></span></button><button class="document-edit" data-edit-document="${esc(doc.id)}" aria-label="${tr('编辑或导出','Edit or export')}">···</button><button class="delete" data-delete-document="${esc(doc.id)}" aria-label="${tr('删除文档','Delete document')}: ${esc(doc.title)}">×</button></div>`).join(''):empty('reading',tr('文字已准备好，<br>只等一个安静的时刻。','A quiet place<br>for words worth keeping.'))}</div></div>`}
  function extractHTML(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,nav,header,footer,aside,form,button,input,iframe,svg,noscript,[hidden],[aria-hidden="true"],.article-tag,.foot,.reader-page-actions').forEach(n=>n.remove());const root=doc.querySelector('article')||doc.querySelector('main')||doc.body;const blocks=new Set(['P','DIV','SECTION','ARTICLE','MAIN','H1','H2','H3','H4','H5','H6','LI','UL','OL','BLOCKQUOTE','PRE','TR']);function collect(node){if(node.nodeType===3)return node.nodeValue;if(node.nodeType!==1)return '';if(node.tagName==='BR')return '\n';const text=Array.from(node.childNodes,collect).join('');if(/^H[1-3]$/.test(node.tagName))return '\n\n'+'#'.repeat(Number(node.tagName[1]))+' '+text+'\n\n';return blocks.has(node.tagName)?'\n\n'+text+'\n\n':text}return {title:doc.querySelector('h1')?.textContent||doc.querySelector('h2')?.textContent||doc.title,text:R.normalize(collect(root))}}
  async function readCurrent(){const page=current();if(!page){toast(tr('先打开一篇文章，或粘贴文字、导入文档。','Open an article first, or paste text / import a file.'));return}if(page.type==='article'){const article=document.querySelector('.browse-content .article');if(!article)return;const extracted=extractHTML(article.outerHTML);open(R.makeDocument({title:pageTitle(page),text:extracted.text,format:'html',source:'zero:read'}),false);return}if(page.type!=='external'){toast(tr('此页面没有可提取的正文，请导入文档或粘贴文字。','This page has no article text. Import a document or paste text.'));return}if(loading)return;loading=true;toast(tr('正在尝试提取网页正文…','Trying to extract the article…'));fetchController=new AbortController();const timeout=setTimeout(()=>fetchController.abort(),20000);try{const response=await fetch(page.url,{credentials:'omit',signal:fetchController.signal});if(!response.ok)throw Error(tr('无法读取该网页。','Could not read this page.'));const mime=response.headers.get('content-type')||'';if(!/text\/(html|plain|markdown)/i.test(mime))throw Error(tr('此页面不是可读取的文本文档。','This page is not a readable text document.'));const reader=response.body?.getReader();if(!reader)throw Error(tr('当前浏览器不支持正文提取。','This browser does not support article extraction.'));let chunks=[],size=0;while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>5*1024*1024){await reader.cancel();throw Error('large')}chunks.push(value)}const text=R.decode(await new Blob(chunks).arrayBuffer());const extracted=/html/i.test(mime)?extractHTML(text):{title:page.title,text};open(R.makeDocument({...extracted,format:/markdown/i.test(mime)?'md':'html',source:page.url}),false)}catch(error){if(error instanceof TypeError)toast(tr('网页未允许跨域读取，请复制正文到阅读资料库。','This website does not allow cross-origin reading. Paste its text into your reading library.'));else notify(error)}finally{clearTimeout(timeout);fetchController=null;loading=false}}
  async function pdfText(buffer){const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('vendor/pdf.worker.mjs',location.href).href;const task=pdfjs.getDocument({data:new Uint8Array(buffer),isEvalSupported:false,useSystemFonts:true});let pdf;try{pdf=await task.promise;if(pdf.numPages>500)throw Error(tr('此 PDF 超过 500 页，请拆分后导入。','This PDF has over 500 pages. Split it before importing.'));let pages=[];let length=0;for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();let text='';for(const item of content.items){if('str'in item)text+=item.str+(item.hasEOL?'\n':' ')}length+=text.length;if(length>R.MAX_TEXT_LENGTH)throw Error('long');pages.push(text);page.cleanup()}return pages.join('\n\n')}finally{if(pdf)await pdf.destroy();else await task.destroy()}}
  let mammothPromise;
  async function docxText(buffer){if(!mammothPromise)mammothPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/mammoth.browser.min.js';script.onload=()=>resolve(window.mammoth);script.onerror=()=>{mammothPromise=null;reject(Error(tr('DOCX 解析器加载失败。','Could not load the DOCX parser.')))};document.head.append(script)});const mammoth=await mammothPromise;return (await mammoth.extractRawText({arrayBuffer:buffer})).value}
  async function importFile(file){if(!file||loading)return;loading=true;renderSheet();try{const kind=R.validateFile(file);const buffer=await file.arrayBuffer();let text='';if(kind==='pdf')text=await pdfText(buffer.slice(0));else if(kind==='docx')text=await docxText(buffer);else {text=R.decode(buffer);if(kind==='html')text=extractHTML(text).text}const doc=R.makeDocument({title:file.name.replace(/\.[^.]+$/,''),text,format:kind,source:file.name,blob:file});await dbOp('readwrite',store=>store.put(doc),'documents');await refresh();open(doc,true);toast(tr('文档已缓存到本地。','Document saved locally.'))}catch(error){notify(error)}finally{loading=false;if(!$('sheet').hidden&&tab==='reading')renderSheet()}}
  async function savePasted(){if(loading)return;loading=true;try{const doc=R.makeDocument({title:$('readingTitle').value,text:$('readingText').value,format:'txt'});await dbOp('readwrite',store=>store.put(doc),'documents');draft={title:'',text:''};await refresh();open(doc,true);toast(tr('文字已缓存到本地。','Text saved locally.'))}catch(error){notify(error)}finally{loading=false}}
  async function load(id){try{const doc=await dbOp('readonly',store=>store.get(id),'documents');if(!doc)throw Error(tr('文档不存在，可能已被浏览器清理。','Document is missing. Browser storage may have been cleared.'));open(doc,true)}catch(error){notify(error)}}
  async function remove(id){if(!confirm(tr('删除此缓存文档？','Delete this saved document?')))return;try{await progressWrite;await dbOp('readwrite',store=>store.delete(id),'documents');if(active?.id===id)close();await refresh()}catch(error){notify(error)}}
  function releaseURL(){if(rawURL){URL.revokeObjectURL(rawURL);rawURL=null}}
  function open(doc,isStored){returnFocus=document.activeElement;rememberPage();stopMedia();closeSheet();releaseURL();active=doc;stored=isStored;settingsOpen=false;focused=false;$('readerPanel').hidden=false;$('app').inert=true;$('readerPanel').classList.toggle('reader-dark',preferences.theme==='dark');renderReader();$('readerPanel').querySelector('[data-reader-action="close"]')?.focus()}
  function settingsHTML(){return `<div class="reader-settings"><div><span>${tr('字号','Size')}</span><button data-reader-action="smaller" aria-label="${tr('缩小字号','Smaller text')}">A−</button><span>${preferences.size}</span><button data-reader-action="larger" aria-label="${tr('放大字号','Larger text')}">A＋</button></div><div><label for="readerLine">${tr('行距','Spacing')}</label><select id="readerLine"><option value="1.65" ${preferences.line===1.65?'selected':''}>${tr('紧凑','Compact')}</option><option value="2" ${preferences.line===2?'selected':''}>${tr('适中','Comfortable')}</option><option value="2.35" ${preferences.line===2.35?'selected':''}>${tr('宽松','Spacious')}</option></select></div><div><label for="readerFont">${tr('字体','Font')}</label><select id="readerFont"><option value="serif" ${preferences.font==='serif'?'selected':''}>${tr('衬线','Serif')}</option><option value="sans" ${preferences.font==='sans'?'selected':''}>${tr('无衬线','Sans serif')}</option></select></div><div><span>${tr('外观','Theme')}</span><button data-reader-action="light" aria-label="${tr('浅色阅读','Light reading')}">○</button><button data-reader-action="dark" aria-label="${tr('深色阅读','Dark reading')}">●</button><div><button data-reader-action="find">${tr('页内查找','Find in text')}</button><button data-reader-action="contents">${tr('目录','Contents')}</button><button data-reader-action="export">${tr('导出文本','Export text')}</button><button data-reader-action="translate">${tr('翻译','Translate')}</button></div></div>`}
  function cacheTextButton(extraClass=''){const saving=pendingSaves.has(active.id),label=stored?tr('当前文本已缓存','Current text saved'):saving?tr('正在缓存当前文本','Saving current text'):tr('缓存当前文本','Save current text');return `<button class="reader-cache-button ${extraClass} ${saving?'is-saving':''}" data-reader-action="save" ${stored||saving?'disabled':''} aria-label="${label}" aria-busy="${saving}">${icon(stored?'check':'download')}</button>`}
  function renderReader(){if(!active)return;const panel=$('readerPanel');panel.setAttribute('aria-label',tr('阅读模式','Reader mode'));panel.classList.toggle('reader-focus',focused);panel.classList.toggle('reader-dark',preferences.theme==='dark');panel.style.setProperty('--reader-size',preferences.size+'px');panel.style.setProperty('--reader-line',preferences.line);panel.style.setProperty('--reader-font',preferences.font==='serif'?'Georgia,"Noto Serif SC","Songti SC",SimSun,serif':'"DM Sans","Noto Sans SC",sans-serif');panel.innerHTML=`<header class="reader-header"><button data-reader-action="close" aria-label="${tr('退出阅读','Close reader')}">${icon('back')}</button><span>${tr('阅读模式','READER')}</span><div class="reader-header-actions">${cacheTextButton('reader-header-cache')}<button data-reader-action="settings" aria-label="${tr('阅读设置','Reading settings')}" aria-expanded="${settingsOpen}">Aa</button></div></header>${settingsOpen?settingsHTML():''}<div class="reader-focus-controls">${cacheTextButton('reader-focus-cache')}<button class="reader-focus-exit" data-reader-action="focus" aria-label="${tr('退出专注','Exit focus')}">⛶</button></div><div class="reader-scroll" tabindex="0" aria-label="${tr('阅读正文','Reading text')}"><div class="reader-text"><div class="reader-eyebrow">${tr('留一点时间，给文字。','A LITTLE TIME FOR WORDS.')} · ${esc(active.format.toUpperCase())}</div><h1>${esc(active.title)}</h1><p class="reader-byline">${active.text?tr(`约 ${Math.max(1,Math.ceil(R.wordCount(active.text)/350))} 分钟阅读`,`${Math.max(1,Math.ceil(R.wordCount(active.text)/220))} min read`):tr('原文档已保存','Original document saved')}${stored?' · '+tr('可离线阅读','Available offline'):''}</p>${active.text?R.renderText(active.text,['md','html'].includes(active.format)):`<div class="reader-no-text"><p>${tr('此文档未提取到文字，可能是扫描版 PDF。原文件已缓存，可以打开查看；此版本暂不支持 OCR。','No text was found. This may be a scanned PDF. The original is saved and can be opened below. OCR is not available in this version.')}</p></div>`}${active.blob?`<button class="secondary reader-original" data-reader-action="original">${icon('external')}${tr('查看 / 下载原文件','View / download original')}</button>`:''}${saveErrors.has(active.id)?`<p class="reader-save-error" role="status">${esc(saveErrors.get(active.id))}</p>`:''}</div></div><footer class="reader-footer"><span class="reader-footer-spacer" aria-hidden="true"></span><span class="reader-percent">${Math.round((active.progress||0)*100)}%</span><button data-reader-action="focus" aria-label="${tr('专注阅读','Focus reading')}">⛶</button></footer><div class="reader-progress"><span style="width:${(active.progress||0)*100}%"></span></div>`;const scroll=panel.querySelector('.reader-scroll');requestAnimationFrame(()=>{if(active&&scroll.isConnected)scroll.scrollTop=(active.progress||0)*Math.max(0,scroll.scrollHeight-scroll.clientHeight)});scroll.addEventListener('scroll',()=>{if(!active)return;active.progress=R.progress(scroll.scrollTop,scroll.scrollHeight,scroll.clientHeight);panel.querySelector('.reader-percent').textContent=Math.round(active.progress*100)+'%';panel.querySelector('.reader-progress span').style.width=active.progress*100+'%';clearTimeout(persistTimer);persistTimer=setTimeout(persistProgress,350)},{passive:true});if($('readerLine'))$('readerLine').onchange=e=>changePreference('line',Number(e.target.value));if($('readerFont'))$('readerFont').onchange=e=>changePreference('font',e.target.value)}
  function changePreference(key,value){preferences[key]=value;save('zr-reader-prefs',preferences);renderReader()}
  function persistProgress(){if(!active||!stored)return progressWrite;const id=active.id,progress=active.progress||0;progressWrite=progressWrite.catch(()=>{}).then(async()=>{const doc=await dbOp('readonly',store=>store.get(id),'documents');if(doc){doc.progress=progress;await dbOp('readwrite',store=>store.put(doc),'documents')}}).catch(()=>toast(tr('阅读进度保存失败。','Could not save reading progress.')));return progressWrite}
  function close(){ZeroTools.closeFind();clearTimeout(persistTimer);persistProgress();$('readerPanel').hidden=true;$('app').inert=!$('sheet').hidden;active=null;releaseURL();refresh();if(returnFocus?.isConnected)returnFocus.focus()}
  async function saveActive(){if(!active||stored||pendingSaves.has(active.id))return;const documentToSave={...active};const id=documentToSave.id;pendingSaves.add(id);saveErrors.delete(id);renderReader();try{await dbOp('readwrite',store=>store.put(documentToSave),'documents');if(active?.id===id){stored=true;await persistProgress()}await refresh();toast(tr('当前文本已缓存，可从资料库 → 阅读离线查看。','Current text saved. Read it offline in Library → Reading.'))}catch(error){const message=tr('缓存失败，请检查浏览器存储权限后重试。','Save failed. Check browser storage permissions and retry.');saveErrors.set(id,message);toast(message)}finally{pendingSaves.delete(id);if(active?.id===id)renderReader()}}
  function original(){if(!active?.blob)return;releaseURL();rawURL=URL.createObjectURL(new Blob([active.blob],{type:active.format==='pdf'?'application/pdf':'application/octet-stream'}));const a=document.createElement('a');a.href=rawURL;if(active.format==='pdf'){a.target='_blank';a.rel='noopener'}else a.download=active.source||active.title+'.'+active.format;a.click()}
  async function editDocument(id){const doc=await dbOp('readonly',store=>store.get(id),'documents');if(!doc)return;const choice=prompt(tr('输入 1 修改标题，2 修改标签，3 导出文本。','Enter 1 to rename, 2 to edit tag, 3 to export text.'),'1');if(choice==='3'){ZeroTools.downloadBlob(new Blob([doc.text],{type:'text/plain;charset=utf-8'}),doc.title+'.txt');return}if(choice==='1'||choice==='2'){const value=prompt(tr(choice==='1'?'标题':'标签',choice==='1'?'Title':'Tag'),choice==='1'?doc.title:doc.tag||'');if(value===null)return;doc[choice==='1'?'title':'tag']=value.slice(0,160);await dbOp('readwrite',store=>store.put(doc),'documents');await refresh()}}
  async function exportBackup(){const all=await dbOp('readonly',store=>store.getAll(),'documents');const records=[];for(const doc of all){const {blob,...rest}=doc;let original=null;if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));original={type:blob.type,data:btoa(binary)}}records.push({...rest,original})}ZeroTools.downloadBlob(new Blob([JSON.stringify({version:1,documents:records})],{type:'application/json'}),'zero-red-reading-backup.json')}
  async function importBackup(file){if(!file)return;try{if(file.size>100*1024*1024)throw Error('large');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.documents)||data.documents.length>1000)throw Error(tr('备份格式不正确。','Invalid backup format.'));const records=[];for(const old of data.documents){if(typeof old.text!=='string'||typeof old.title!=='string')throw Error(tr('备份内容不完整。','Incomplete backup.'));let blob=null;if(old.original?.data){const bytes=Uint8Array.from(atob(old.original.data),c=>c.charCodeAt(0));if(bytes.byteLength>R.MAX_FILE_BYTES)throw Error('large');if(old.format==='pdf'&&new TextDecoder().decode(bytes.subarray(0,5))!=='%PDF-')throw Error(tr('PDF 原文件无效。','Invalid original PDF.'));blob=new Blob([bytes],{type:old.format==='pdf'?'application/pdf':'application/octet-stream'})}const doc=R.makeDocument({title:old.title,text:old.text,source:String(old.source||''),format:['txt','md','html','pdf','docx'].includes(old.format)?old.format:'txt',blob});doc.progress=Math.max(0,Math.min(1,Number(old.progress)||0));doc.tag=String(old.tag||'').slice(0,160);records.push(doc)}await dbOp('readwrite',store=>{let request=store.count();for(const doc of records)request=store.put(doc);return request},'documents');await refresh();toast(tr('阅读备份已导入。','Reading backup imported.'))}catch(error){notify(error)}}
  function contents(){if(!active)return;settingsOpen=false;renderReader();const headings=Array.from($('readerPanel').querySelectorAll('.reader-text h1,.reader-text h2,.reader-text h3,.reader-text h4'));const tray=document.createElement('div');tray.className='reader-contents';tray.innerHTML=`<strong>${tr('目录','Contents')}</strong><button class="contents-close" aria-label="${tr('关闭','Close')}">×</button>`;headings.forEach(heading=>{const button=document.createElement('button');button.textContent=heading.textContent;button.onclick=()=>{heading.scrollIntoView({block:'start',behavior:'smooth'});tray.remove()};tray.append(button)});tray.querySelector('.contents-close').onclick=()=>tray.remove();$('readerPanel').append(tray)}
  function translate(){if(!active)return;const selected=window.getSelection()?.toString();const text=selected||active.text;if(text.length>5000){toast(tr('请先选择不超过 5000 字的文字再翻译。','Select up to 5,000 characters to translate.'));return}const url=new URL('https://translate.google.com/');url.search=new URLSearchParams({sl:'auto',tl:lang==='zh'?'zh-CN':'en',text,op:'translate'}).toString();window.open(url.href,'_blank','noopener,noreferrer')}
  function init(){const saved=read(localStorage,'zr-reader-prefs',{});preferences={size:[14,16,18,20,22,24,26,28].includes(saved?.size)?saved.size:18,line:[1.65,2,2.35].includes(saved?.line)?saved.line:2,font:saved?.font==='sans'?'sans':'serif',theme:saved?.theme==='dark'?'dark':'light'};document.addEventListener('change',e=>{if(e.target.id==='documentFile')importFile(e.target.files[0]);if(e.target.id==='readingBackupFile')importBackup(e.target.files[0])});document.addEventListener('input',e=>{if(e.target.id==='readingSearch'){documentQuery=e.target.value;document.querySelectorAll('.reading-item').forEach(row=>{const id=row.querySelector('[data-read-document]')?.dataset.readDocument,doc=documents.find(d=>d.id===id);row.hidden=!!documentQuery&&!([doc?.title,doc?.text,doc?.tag].some(value=>String(value||'').toLocaleLowerCase().includes(documentQuery.toLocaleLowerCase())))})}if(e.target.id==='readingTitle')draft.title=e.target.value;if(e.target.id==='readingText')draft.text=e.target.value});document.addEventListener('submit',e=>{if(e.target.id==='readingForm'){e.preventDefault();savePasted()}});document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-document]');if(edit){editDocument(edit.dataset.editDocument);return}if(e.target.closest('[data-reader-library="backup"]')){exportBackup().catch(notify);return}const item=e.target.closest('[data-read-document]');if(item){load(item.dataset.readDocument);return}const removeButton=e.target.closest('[data-delete-document]');if(removeButton){remove(removeButton.dataset.deleteDocument);return}const action=e.target.closest('[data-reader-action]')?.dataset.readerAction;if(!action)return;if(action==='close')close();if(action==='find'){settingsOpen=false;renderReader();ZeroTools.find()}if(action==='contents')contents();if(action==='export'&&active)ZeroTools.downloadBlob(new Blob([active.text],{type:'text/plain;charset=utf-8'}),active.title+'.txt');if(action==='translate')translate();if(action==='settings'){settingsOpen=!settingsOpen;renderReader()}if(action==='smaller')changePreference('size',Math.max(14,preferences.size-2));if(action==='larger')changePreference('size',Math.min(28,preferences.size+2));if(action==='light'||action==='dark')changePreference('theme',action);if(action==='focus'){focused=!focused;settingsOpen=false;renderReader()}if(action==='save')saveActive();if(action==='original')original()});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.import-document')){e.preventDefault();$('documentFile')?.click();return}if(e.key==='Escape'&&!$('readerPanel').hidden){e.stopImmediatePropagation();if(focused){focused=false;renderReader()}else close()}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)persistProgress()});window.addEventListener('pagehide',persistProgress);refresh()}
  async function reset(){await progressWrite;close();await progressWrite;await dbOp('readwrite',store=>store.clear(),'documents');documents=[];draft={title:'',text:''}}
  return {init,libraryHTML,refresh,readCurrent,reset,render:renderReader,isOpen:()=>!!active};
})();
